python scripts/server/run_entex_probe_matrix.py --task p1 --subtask tibial_nerve --loci data/entex/v1/p1/tibial_nerve_loci.parquet --mapping-dir data/entex/v1/p1/mapping_tibial_nerve --full-segments server_workspace/data/processed/hprc_r2_sv/full_segments.csv.gz --manifest server_workspace/data/benchmarks/hprc_r2_pretrain_5mb_paired/manifest.csv --feature-cache server_workspace/data/processed/hprc_r2_ccre_screen_v4_features.npz --sequence-cache server_workspace/results/frozen_sequence_fm_cache_20260815/hprc_target_union_sequence_fm.npz --results-root server_workspace/results/full_multicohort_server_20260806 --out-root results/entex/v1/p1/tibial_nerve --topology-cache-root results/entex/v1/topology_cache_all_reference --cache-all-reference-targets --gpus 0,1,2,3
